return {
    ["011010000110111101101101011001010110100001\n011010110101100101011010001000011011011001\n101101000011011110111101101011010110010101\n101101000011011110110110100000110010101100\n011011010110010101101000011011110110101100\n000110010101100001101111011101011001010111\n……"] = false,
    ["<P_Heart>（一般人会这么称呼狒狒吗……）</>"] = "<P_Heart>(Разве обычный человек назвал бы павиана так?..)</>",
    ["<P_Heart>（不好，难道真是查尼斯门？）</>"] = "<P_Heart> (О нет, неужели это действительно Врат Чаниса?) </>",
    ["<P_Heart>（不知道他们今晚会不会来，在这里蹲守看看。 ）</>"] = "<P_Heart>(Не знаю, придут ли они сегодня вечером. Подожду здесь в засаде и посмотрю.)</>",
    ["<P_Heart>（伸懒腰）</>自从来到这边，我还是第一次吃得这么饱！"] = "<P_Heart>(Потягивается)</> С тех пор как я здесь, я впервые так наелся!",
    ["<P_Heart>（你的意思是，潜入别人的花园挖出一块菜地……）</>"] = "<P_Heart>(Вы имеете в виду проникнуть в чужой сад и выкопать там грядку…)</>",
    ["<P_Heart>（促狭）</>当然，我们都是说“罗塞尔语”的同胞嘛。"] = "<P_Heart>(Лукаво)</> Конечно, мы же все соотечественники, говорящие на «руселльском».",
    ["<P_Heart>（兴奋）</>好！{{PlayerName}}，来帮我备菜吧！"] = "<P_Heart>(Взволнованно)</> Отлично! {{PlayerName}}, помоги мне приготовить продукты!",
    ["<P_Heart>（到底是演员还是舞台的问题？继续听下去也没有意义，还是去剧场内看看吧……）</>"] = "<P_Heart>(Дело в актёрах или в сцене? Слушать дальше нет смысла, лучше посмотреть внутри театра…)</>",
    ["<P_Heart>（可普通人制作的护身符达不到这个效果的……）</>"] = "<P_Heart>(Но обереги, сделанные обычными людьми, не могут дать такой эффект…)</>",
    ["<P_Heart>（咆哮）</>这班再上下去简直是一种精神污染！"] = "<P_Heart>(Рычит)</>Ещё немного такой работы, и это будет настоящее ментальное загрязнение!",
    ["<P_Heart>（咽口水）</>是熟悉的味道。"] = "<P_Heart>(Сглатывает слюну)</>Знакомый вкус.",
    ["<P_Heart>（嗯嗯，豆花甜咸之争以外，还有很多隐藏的辣派啊……）</>"] = "<P_Heart>(Ага, помимо спора о сладком и солёном тофу-пудинге, есть ещё немало скрытых любителей острого...)</>",
    ["<P_Heart>（奇怪的音韵，不是鲁恩语，也不是任何一种已知的神秘学语言。但为什么……我会觉得很熟悉？）</>"] = "<P_Heart>(Странные созвучия: это не лоэнский и не какой-либо известный мистический язык. Но почему... они кажутся мне такими знакомыми?)</>",
    ["<P_Heart>（尴尬地咳嗽）</>花园运营者说的恶臭，很有可能是我们导致的。"] = "<P_Heart>(Неловко кашляет)</>Вонь, о которой говорил управляющий садом, вполне возможно, наших рук дело.",
    ["<P_Heart>（尴尬）</>你误会了，那是，是我的抱怨啊……"] = "<P_Heart>(Смущённо)</>Вы неправильно поняли, это была... это была моя жалоба...",
    ["<P_Heart>（快走！）</>"] = "<P_Heart>(Бежим!)</>",
    ["<P_Heart>（思索）</>我相信你们，但是恶臭并没有消失。"] = "<P_Heart>(Задумчиво)</>Я вам верю, но вонь никуда не делась.",
    ["<P_Heart>（恍然）</>确实如此！很可怕的能力，不仅能迷惑非凡者，而且它的根系发达，覆盖了整个花园，我们脚下全是遗骸。这或许能解释蔬菜惊人的生长速度。"] = "<P_Heart>(Осознав)</>Точно! Жуткая способность: она не только морочит Потусторонних, но и корни у неё так разрослись, что покрывают весь сад, и под ногами у нас одни останки. Возможно, это объясняет поразительную скорость роста овощей.",
    ["<P_Heart>（恶臭、深夜的秘密行动和呓语……很可能是非凡事件。）</>"] = "<P_Heart>(Вонь, тайные ночные дела и бормотание... Скорее всего, это потустороннее происшествие.)</>",
    ["<P_Heart>（愤怒）</>经理是卷毛狒狒吗？脑子被吃了吗？不，不能侮辱狒狒。"] = "<P_Heart>(Гневно)</>Управляющий что, кудрявый бабуин? Ему мозги съели? Нет, нельзя оскорблять бабуинов.",
    ["<P_Heart>（我竟然真的会这种语言！也就是说，他们和我的过去或许有关……）</>"] = "<P_Heart>(Я и вправду знаю этот язык! Значит, они, возможно, связаны с моим прошлым...)</>",
    ["<P_Heart>（扶额）</>够了。"] = "<P_Heart>(Хватается за лоб)</>Хватит.",
    ["<P_Heart>（扶额）</>难道天上真的会掉迪西馅饼吗？"] = "<P_Heart>(Хватается за лоб)</>Неужели пироги Диси и правда падают с неба?",
    ["<P_Heart>（抱怨）</>不行不行，身上班味太重了，我得想个办法……"] = "<P_Heart>(Жалуется)</>Нет-нет, от меня слишком разит офисом, надо что-то придумать...",
    ["<P_Heart>（按耐不住）</>……不管了！人是铁，饭是钢，我也要吃！"] = "<P_Heart>(Не в силах сдержаться)</>……Да ну всё! Пустое брюхо к труду глухо — я тоже буду есть!",
    ["<P_Heart>（捂鼻子）</>奇怪，还是很臭，像什么东西暗中腐烂的气味。"] = "<P_Heart>(Зажимает нос)</>Странно, всё равно воняет, как будто что-то тайно гниёт.",
    ["<P_Heart>（摇头）</>我不会轻易地答应他的，阿斯塔的离职虽然有个人因素，但是葛朗经理对剧组的压榨也是一大原因。"] = "<P_Heart>(Качает головой)</>Я не соглашусь на его предложение так легко. Хотя у ухода Асты были и личные причины, эксплуатация съёмочной группы управляющим Гранном тоже сыграла большую роль.",
    ["<P_Heart>（摇头）</>都是过去的事了，来自非凡者无意的举动，对普通人而言，可能是一场灾难……我在尽力补偿。"] = "<P_Heart>(Качает головой)</>Всё это в прошлом. Непреднамеренный поступок Потустороннего может обернуться для обычного человека бедствием... Я стараюсь всё компенсировать.",
    ["<P_Heart>（放松）</>哦哦，是老乡啊。以前怎么没见过你？"] = "<P_Heart>(Расслабленно)</>О, так вы земляк. Почему я раньше вас не видел?",
    ["<P_Heart>（狒狒喜欢吃水果……先试着帮他喂饱狒狒吧。）</>"] = "<P_Heart>(Бабуины любят фрукты... Для начала попробуем помочь ему накормить бабуина.)</>",
    ["<P_Heart>（疑惑）</>为什么要道歉？"] = "<P_Heart>(Недоумённо)</>За что вы извиняетесь?",
    ["<P_Heart>（看不见的力量？难道这件事另有隐情。）</>"] = "<P_Heart>(Невидимая сила? Неужели за этим кроется что-то ещё.)</>",
    ["<P_Heart>（看来他们就是潜入者了，我要先出手，让他们没有准备。一、二……）</>"] = "<P_Heart>（Похоже, это и есть лазутчики. Ударю первым, пока они не готовы. Раз, два…）</>",
    ["<P_Heart>（眼睛一亮）</>我还以为那批种子都不行了，看来土地还是肯给我们面子。"] = "<P_Heart>（Глаза загораются）</>А я уж думал, что те семена пропали. Похоже, земля всё-таки смилостивилась над нами.",
    ["<P_Heart>（突然失忆？用灵视看看。）</>"] = "<P_Heart>（Внезапная потеря памяти? Посмотрю с помощью Истинного Зрения.）</>",
    ["<P_Heart>（笑眯眯）</>托这两位“耕种者”的福，终于可以吃到韭菜猪肉饺子、蒜蓉菜心和虎皮尖椒了。"] = "<P_Heart>（Улыбается）</>Благодаря этим двум «земледельцам» я наконец-то поем пельмени со свининой и черемшой, чесночную капусту и острый перец по-тигриному.",
    ["<P_Heart>（脸色发绿）</>我不想吃了。"] = "<P_Heart>（Лицо позеленело）</>Я больше не хочу есть.",
    ["<P_Heart>（艾玛已经序列7，涉及记忆和心理相关的问题……得谨慎一点。）</>"] = "<P_Heart>（Эмма уже на Последовательности 7, а тут речь о памяти и психике… Надо быть осторожнее.）</>",
    ["<P_Heart>（虽然这书看着也不怎么靠谱……）</>"] = "<P_Heart> (Хотя эта книга тоже не выглядит очень достоверной...) </>",
    ["<P_Heart>（要不要帮她解除失忆的心理暗示？）</>"] = "<P_Heart>（Не помочь ли ей снять психологическое внушение, из-за которого она потеряла память?）</>",
    ["<P_Heart>（诶、我怎么忽然听懂了？！）</>"] = "<P_Heart>（Э? Почему я вдруг всё понял?!）</>",
    ["<P_Heart>（赞许）</>你很敏锐，那个半成品护身符被我灌注了些许灵性，能够让帕金娜不知不觉避开相当程度的厄难……"] = "<P_Heart>（Одобрительно）</>Ты очень проницателен. Я вложил в этот недоделанный амулет немного Духовности, и он незаметно помогает Пакине избегать значительной части бед…",
    ["<P_Heart>（还以为你想起自己是非凡者了……）</>"] = "<P_Heart>（А я думал, ты вспомнил, что ты Потусторонний…）</>",
    ["<P_Heart>（这就是刻在灵体里的种族天赋吗？）</>"] = "<P_Heart>（Так вот он какой, расовый дар, вырезанный в духовном теле?）</>",
    ["<P_Heart>（那边好像有一对新婚的夫妻，过去看看吧。）</>"] = "<P_Heart> (Кажется, там молодожены, пойдем посмотрим.) </>",
    ["<P_Heart>（阿斯塔看起来很正常，保险起见，还是用灵视检查一下。）</>"] = "<P_Heart>（Аста выглядит вполне нормально, но на всякий случай проверю её Истинным Зрением.）</>",
    ["<P_Heart>（难道米莉他们还在夜间施肥？得再去问问。）</>"] = "<P_Heart>（Неужели Милли и остальные всё ещё удобряют по ночам? Надо расспросить ещё раз.）</>",
    ["{{PlayerName}}，你回来了。"] = "{{PlayerName}}, ты вернулся.",
    ["{{PlayerName}}，你熟悉她的故事，对于让她失忆的心理暗示，你有什么想法吗？"] = "{{PlayerName}}, ты хорошо знаешь её историю. Что ты думаешь о психологическом внушении, из-за которого она потеряла память?",
    ["{{PlayerName}}，我想起来了！"] = "{{PlayerName}}, я вспомнил!",
