    ["“欢 迎 来 到 真 实 的 世 界 ！”\n陷入黑暗前，你听到疯癫的男士这样说。"] = "«Добро пожаловать в реальный мир!» Вы слышали слова сумасшедшего до того, как \n упал во тьму.",
    ["“浇水施肥”……难道……"] = "«Полив и удобрение»... неужели...",
    ["“海盗女王将贵族小姐按在墙上，邪笑道：‘就算你喊破喉咙也没人来救你的！’话音未落，格尔曼从天而降，逼退女王：‘放开她。’”"] = "«Королева пиратов прижала благородную даму к стене и ухмыльнулась: «Даже если ты будешь кричать до тех пор, пока у тебя не перебьется горло, никто не придет тебя спасти!» Прежде чем слова исчезли, Герман спустился с неба, заставив королеву отступить: «Отпусти ее».",
    ["“观众”途径所需的魔药材料，它具有一定活着的特性，能够发出催眠的声音和气味捕捉猎物。"] = "Материал для зелья Пути «Зритель». Обладает некоторыми свойствами живого существа и может издавать усыпляющие звуки и запахи, чтобы поймать добычу.",
    ["……"] = false,
    ["……不会因为我吧？"] = "...Это же не из-за меня?",
    ["……不，不要提我们的菜。<P_Heart>（欲呕）</>我们的菜是在尸体上长出来的！"] = "...Нет, не говорите про нашу еду. <P_Heart>(Тошнит)</> Наша еда растёт на трупах!",
    ["……先找个地方坐坐，我有点撑不住了。 "] = "...Давайте сначала найдем место, где можно присесть; Я больше не могу держаться.",
    ["……原来我曾经是个不平凡的人。"] = "...Оказывается, когда-то я был необыкновенным человеком.",
    ["……嗯！"] = "...Угу!",
    ["……大概是名人吧，印象里人们为了争抢我演出的票，总是互相踩掉鞋子，在我眼前大声欢呼……"] = "...Наверное, я был знаменитостью: помню, что люди, борясь за билеты на мои выступления, всё время наступали друг другу на ноги и громко ликовали у меня перед глазами...",
    ["……它叫波利，虽然它嘴很坏，但一直陪着我。"] = "...Её зовут Полли. Хоть у неё и дурной язык, она всегда была рядом со мной.",
    ["……情趣……海盗女王和贵族小姐……"] = "...Пикантно... королева пиратов и благородная леди...",
    ["……我、我真的不是明星？"] = "...Я-я правда не звезда?",
    ["……我想辞职很久了，我怀疑是在做这个护身符的时候我离职的念头太强了，才害你被停职的。"] = "...Я давно хотел уволиться. Подозреваю, что, когда я делал этот амулет, моё желание уйти было так сильно, что из-за него тебя отстранили от работы.",
    ["……抱歉。"] = "……Извини.",
    ["……是我冒失了。"] = "...Это была моя опрометчивость.",
    ["……真的吗！您也觉得这里有神秘力量的影响？"] = "...Правда?! Вы тоже думаете, что здесь есть влияние таинственных сил?",
    ["……算了，来都来了。"] = "...Забудь об этом, я уже здесь.",
    ["……给我盛点。"] = "...Положи мне немного.",
    ["《大冒险家：格尔曼传奇》？这版本倒是头一回见……"] = "«Великий авантюрист: Легенда о Германе»? Эту версию я вижу впервые...",
    ["《天鹅之梦》改编后有个从楼梯跌落的表演……我发誓，那是我见过的最美的画面，帕金娜就像那无助的天鹅，被剪断了翅膀，从楼梯上……"] = "В экранизации «Лебединого сна» есть сцена падения с лестницы... Клянусь, это самое прекрасное, что я видел: Пакина, словно беспомощный лебедь с подрезанными крыльями, падает с лестницы...",
    ["一点小惩罚。从今天开始，他们会守护附近，做一个真正的“保护者”。"] = "Небольшое наказание. С этого дня они будут охранять окрестности и станут настоящими «защитниками».",
    ["一点心意，希望你能保密，普通人还是不要知晓非凡力量的存在比较好。"] = "Небольшой знак благодарности. Надеюсь, вы сохраните это в тайне: обычным людям лучше не знать о существовании Потусторонних сил.",
    ["一点点……小情趣？本以为这里偏僻，不会有人听见的。"] = "Немного... романтики? Я думал, место глухое и нас никто не услышит.",
    ["一片草地？"] = "Участок травы?",
    ["上班时看到无数张期待的脸，听到无数声“谢谢”……"] = "На работе видеть бесчисленные ожидающие лица и слышать бесчисленные «спасибо»...",
    ["不、不是的。"] = "Н-нет, это не так.",
    ["不、不用了，我只是陪同他来的。"] = "Нет, не надо, я просто сопровождаю его.",
    ["不、不行，请再给我一些时间吧……"] = "Н-нет, пожалуйста, дайте мне ещё немного времени...",
    ["不吃"] = "Не есть",
    ["不对啊。格尔曼什么时候在慈善医院做过义工了？那是去执行秘密任务，写的什么乱七八糟的……"] = "Это неправильно. Когда Герман когда-либо работал волонтером в благотворительной больнице? Это было для секретной миссии, что за бред здесь написан...",
    ["不对，你肯定在骗我，驯兽师也假装不认识我，你们是同伙！"] = "Нет, ты точно меня обманываешь, Укротитель тоже притворился, что не знает меня, вы заодно!",
    ["不帮她"] = "Не помогать ей",
    ["不是愚人号吗"] = "Разве это не Корабль дураков?",
    ["不是的！我说的是真的！你们都是听说，我是亲眼所见啊！"] = "Нет! Я говорю правду! Вы все слышали это от других, а я видел это своими глазами!",
    ["不知道啊，昨天来了，前天……似乎也来了，看样子明天还会来。"] = "Я не знаю. Они пришли вчера, позавчера... кажется, они и тогда пришли. Похоже, завтра они придут снова.",
    ["不管我怎么散味除臭，第二天那该死的臭味又会回来！"] = "Сколько ни проветривай и ни выводи запах, на следующий день проклятая вонь возвращается!",
    ["为您效力是我们的荣幸，女士……"] = "Для нас честь служить вам, госпожа...",
    ["也不能说白忙活。您这份致敬，还是……挺特别的。"] = "Я бы не сказал зря. Ваша дань уважения была... совершенно уникальной.",
    ["书上写的！你们看，这儿明明白白写着——"] = "В книге так сказано! Смотри, здесь ясно написано —",
    ["书摊老板说是典藏版，花了我不少钱。我想照着格尔曼做过的事也做一遍，回头好跟女儿搭上话。您能否陪我走一趟？替我做个见证。"] = "Владелец книжного ларька сказал, что это коллекционное издание, оно мне обошлось довольно дорого. Я хочу сделать то же, что и Герман, чтобы позже завязать разговор с дочерью. Не могли бы вы сопровождать меня? Стань для меня свидетелем.",
    ["事故的影响还在持续，剧场很冷清啊……"] = "Последствия происшествия всё ещё ощутимы, в театре так пусто...",
    ["什么意外？那是表演事故！我可是高价收的票，就是冲她那“天鹅跌落”来的。"] = "Какая случайность? Это была накладка в выступлении! Я дорого заплатил за билет, пришёл ради её «Падения лебедя».",
    ["今天她休息，应该在家，我带你过去。"] = "Сегодня у неё выходной, должна быть дома. Я провожу вас.",
    ["今天谢谢你……{{先生|女士}}。"] = "Спасибо за сегодня... {{Mr.|Ms.}}.",
    ["从现在起，你们就是我忠实的奴隶了。"] = "Отныне вы мои верные рабы.",
    ["他们称赞我……他们依赖我……"] = "Они хвалят меня... они полагаются на меня...",
    ["他在那里吆喝多久了？"] = "Как долго он там кричал?",
    ["他是你的粉丝，希望你能回剧场表演。"] = "Он ваш поклонник и надеется, что вы вернётесь выступать в театр.",
    ["代价呢？"] = "А цена?",
    ["仪式结束之后，我们还可以留下来帮忙打扫场地。"] = "После завершения церемонии мы можем остаться и помочь прибрать место.",
    ["任何馈赠都有代价，我担心……"] = "У любого дара есть цена, и я опасаюсь...",
    ["会是什么导致的呢……"] = "Что же могло это вызвать...",
    ["但我一直待在帐篷里训练亲亲狒狒，不太能感受世界的纷扰，连团长的脸都快忘了——别告诉团长啊！"] = "Но я всё время сидел в шатре и дрессировал целующихся бабуинов, поэтому почти не чувствую мирской суеты. Лицо директора труппы уже почти забыл — только не говорите ему!",
    ["但我早就找到了生活的意义。"] = "Но смысл жизни я нашёл уже давно.",
    ["但确实有看不见的力量阻挡了我，经理！经理……"] = "Но меня действительно остановила невидимая сила, менеджер! Менеджер...",
    ["但野生植株移栽和培育在野地有很多困难，于是我们借助了花园的温湿度条件。"] = "Но пересадка и выращивание диких растений в поле сопряжены с трудностями, поэтому мы воспользовались температурой и влажностью сада.",
    ["住、住手！快放开……她？"] = "С-стоп! Отпусти ее?",
    ["你不信的话……咳咳，我给你表演一下完整版。"] = "Не веришь... кхе-кхе, я покажу тебе полную версию.",
    ["你们好，请问剧场发生了什么吗？"] = "Здравствуйте, что случилось в театре?",
    ["你们应该采取了一些应对措施？"] = "Вы, должно быть, приняли какие-то меры?",
    ["你们看看这个。"] = "Посмотрите на это.",
    ["你们这代年轻人。这是韭菜，旁边是菜心和辣椒。"] = "Вот молодёжь нынче. Это лук-порей, а рядом цайсин и перец.",
    ["你会过上你想要的生活。"] = "Ты будешь жить так, как хочешь.",
    ["你别说，这男人也真是厉害，把一个慈悲的修女，逼到要为自己无心的善举后悔终生的地步。"] = "Что не говорите, этот человек поистине грозен, заставляя сердобольную монахиню до конца жизни сожалеть о своих нечаянных добрых делах.",
    ["你去哪了？没有你，游客们怎么办！"] = "Где ты был? Без тебя что делать туристам?!",
    ["你吃还是不吃？"] = "Ты будешь есть или нет?",
    ["你呢？"] = "А ты?",
    ["你好，你在和狒狒说话吗？"] = "Здравствуйте, вы разговариваете с бабуином?",
    ["你好，那是我的票。"] = "Здравствуйте, это мой билет.",
    ["你就吹吧！我看你什么传说也没听过，只好自己现编了一个！"] = "Да заливай больше! Ты небось ни одной легенды не слышал, вот и выдумал сейчас на ходу!",
    ["你想说什么？"] = "Что ты хочешь сказать?",
    ["你想起什么了？"] = "Что ты вспомнил?",
    ["你想起来了？！"] = "Ты вспомнил?!",
    ["你抢了别人的马戏团门票？！"] = "Ты отнял чужой билет в цирк?!",
    ["你敢抢警察的票！"] = "Как ты смеешь отнимать билет у полицейского!",
    ["你没骗我？我只是个卖票的？"] = "Ты меня не обманываешь? Я всего лишь продавец билетов?",
    ["你认识我！我果然是明——"] = "Ты меня знаешь! Я так и знал, я точно Мин—",
    ["你？你随意，水果在那边。"] = "Вы? Как хотите, фрукты вон там.",
    ["做得不错嘛，好啦，别弄得那么紧张，我是米莉，那边高的是老詹，胖的是大迪。"] = "Неплохо, неплохо. Ну все, не напрягайтесь так. Я Мили, вон тот высокий — Старина Джеймс, а толстый — Большой Ди.",
    ["停，你到底想说什么？"] = "Стой, что ты на самом деле хочешь сказать?",
    ["先不说这个，我看到那封信了，你要离开？靠什么生活？那高达几十苏勒的存款？"] = "Оставим это. Я видел то письмо. Ты уезжаешь? На что ты будешь жить? На накопления в несколько десятков сулей?",
    ["先生，您这本是盗版书。"] = "Сэр, эта ваша книга — пиратская копия.",
    ["先生，能耽误你一点时间吗？我想问问你刚才说的事 。"] = "Сэр, не уделите мне минутку? Я хотел бы расспросить о том, что вы сейчас сказали.",
    ["克服耕种过程的困难也是消化魔药的重要环节。我们会找到其他无臭增产的解决方案。"] = "Преодоление трудностей выращивания — тоже важная часть переваривания зелья. Мы найдём другие решения для повышения урожая без запаха.",
    ["再卖掉两束花，钱就能凑齐了……"] = "Продам ещё два букета цветов, и денег хватит...",
    ["出示警徽"] = "Покажите значок полиции",
    ["初次看演出的大朋友，也可享受八折优惠！"] = "Взрослые, впервые пришедшие на представление, тоже получат скидку 20%!",
    ["别听她的，我叫詹姆斯，你好。"] = "Не слушай её, меня зовут Джеймс, здравствуй.",
    ["别担心，这是苏茜女士特殊的治疗方式。"] = "Не волнуйся, это особый способ лечения госпожи Сьюзи.",
    ["别这么说，你看这片土地，它可能经历过干旱洪水，又成为许多人的葬身之地。不还是能种出茂盛的、好吃的菜吗？"] = "Не говори так, посмотри на эту землю: она, возможно, пережила засухи и наводнения, стала могилой для многих. Но разве на ней не растут пышные, вкусные овощи?",
    ["到了，阿斯塔！阿斯塔——"] = "Мы на месте, Аста! Аста!..",
    ["剧场门口围着好多人，好像在看什么？"] = "У входа в театр столпилось много людей. На что они смотрят?",
    ["包括投资，也包括那个护身符？"] = "Включая вложения, а также тот амулет?",
    ["占位"] = "Инфо",
    ["即使无法真正摆脱非凡者的身份，我也找到了更想做的事。"] = "Даже если я не смогу по-настоящему избавиться от статуса Потустороннего, я нашёл дело, которым хочу заниматься больше.",
    ["原来是这样，那我们后援会定期有活动，您可以带女儿一起来啊！"] = "Вот оно что! В нашем клубе поддержки регулярно проходят мероприятия, можете прийти вместе с дочерью!",
    ["叒唻给菜圎浇渁孒。"] = "Снова пришёл поливать огород.",
    ["只留下一根羽毛……用卜杖寻路追上去！"] = "Осталось лишь одно перо… Следуй за ними с помощью поиска пути маятником!",
    ["叫一声姐姐，我就教你。"] = "Назови меня сестрой, и я тебя научу.",
    ["可以带我去现场看一下吗？"] = "Можете отвести меня на место, чтобы я посмотрел?",
    ["可怜的玛蒂尔达！只不过随手给他拿了一本经书，就被他缠得连门也不敢出。"] = "Бедная Матильда! Она только что вручила ему Священное Писание, а теперь он так приставает к ней, что она даже не осмеливается выйти на улицу.",
    ["可是，这批蔬菜现在正是关键期……"] = "Но эта партия овощей сейчас в самой важной поре...",
    ["可那些负面情绪让我无法入睡……"] = "Но эти негативные эмоции не дают мне уснуть...",
    ["吃"] = "Есть",
    ["吓人家一跳，还以为有危险呢。"] = "Ох, напугали! А я уж подумала, опасность.",
    ["听说教堂地下关押着好多凶猛的邪兽，要不是大主教镇压着，它们早就跑出来吃人了！"] = "Я слышал, что в подвале собора заперто множество свирепых злых зверей, и если бы не архиепископ, подавляющий их, они бы давно выбежали есть людей!",
    ["呃……晚上好。"] = "Э-э... добрый вечер.",
    ["呃……罗塞尔大帝说过“马车行驶到山前自然会有路”，总会有办法的。"] = "Э-э... Император Рассел говорил: «Когда карета доедет до горы, дорога найдётся сама». Выход всегда найдётся.",
    ["告诉汤姆和你的其他同事，为了他们的安全，晚上不要再来花园。黑影的事我来解决。"] = "Передай Тому и остальным коллегам: ради их безопасности пусть больше не приходят в сад по ночам. С чёрной тенью я разберусь сам.",
    ["呕——"] = "Фу-",
    ["呕——这什么东西——"] = "Кх-э-э... Что это за дрянь?..",
    ["呕……确实，好臭！"] = "Бе-е... и правда, как воняет!",
    ["咦？那边好像有争吵的声音？"] = "О? Кажется, там кто-то ругается?",
    ["咳咳……"] = "Кхм...",
    ["咳咳！"] = "Кхм!",
    ["咳咳，宫廷玉液酒，下一句是什么？"] = "Кхм, «Дворцовое яшмовое вино»... какая там следующая строчка?",
    ["咳咳，抱歉，它不是骂你，票还你。"] = "Кхм, простите, это не ругательство в ваш адрес. Вот ваш билет.",
    ["哈哈哈！你别说，这还真是他能做出来的事。"] = "Ха-ха-ха! Не говорите, что он действительно сделал бы это.",
    ["哎哎哎，你们有没有听过圣赛缪尔教堂的恐怖传说？"] = "Эй-эй, ребята, вы слышали ужасную легенду о соборе Святого Самуила?",
    ["哦，好心的{{先生|女士}}，愿大地庇佑您。"] = "О, добрый {{господин|госпожа}}, да хранит вас земля.",
    ["哼，我刚才没说完，除了这个月的保护费，她还得交下个月的……"] = "Хм, я ещё не договорил: кроме платы за защиту за этот месяц, ей придётся заплатить и за следующий...",
    ["啊！时间要到了，我先走了！"] = "Ах! Время вышло, я побежал!",
    ["啊，是{{PlayerName}}！"] = "О, это {{PlayerName}}!",
    ["啊？"] = "Хм?",
    ["啊？<P_Heart>（听着很不可靠……）</>"] = "А? <P_Heart>(Звучит не очень надёжно...)</>",
    ["嗒哒，看！"] = "Та-дам, смотри!",
    ["嗯……奇变偶不变的下一句？"] = "Хм... а что идёт дальше после «нечётное меняется, чётное нет»?",
    ["嗯，她决定对自己进行心理暗示时，一定做好了接受任何后果的准备。"] = "Да, когда она решила применить к себе психологическое внушение, она наверняка была готова принять любые последствия.",
    ["嘿嘿，你好，我是迪安，叫我大迪也行。"] = "Хе-хе, здравствуйте, я Дин, можете звать меня Большой Дин.",
    ["嘿嘿，做都做了，不能浪费食物。我就吃一点。"] = "Хе-хе, раз уж приготовили, нельзя тратить еду зря. Я съем совсем чуть-чуть.",
    ["回家，把照片给她看。"] = "Иди домой и покажи ей фотографию.",
    ["回想和园丁的对话"] = "Вспомнить разговор с садовником",
    ["回想起来……如果不是你提醒，我们三人竟然这么长时间都没注意到臭味！"] = "Если подумать... не напомни ты нам, мы втроём так долго не замечали бы вони!",
    ["场地费的事，我再向主教大人请示一下，你们先回去好好准备吧。"] = "Что касается платы за место, я еще раз проконсультируюсь с епископом. Вам следует вернуться и хорошо подготовиться.",
    ["多谢女士，他们这是……"] = "Благодарю, госпожа. Они же...",
    ["大锤八十！接！"] = "Кувалда за восемьдесят! Лови!",
    ["天哪——谢谢你，尊敬的{{先生|女士}}，感谢你的祝福。到时候——"] = "О боже, спасибо, уважаемый {{Mr.|Ms.}}, спасибо за ваши благословения. Когда придет время —",
    ["失忆？"] = "Потеря памяти?",
    ["失忆？你需要帮助吗？我是警察，这是我的警徽。"] = "Потеря памяти? Вам нужна помощь? Я полицейский, вот мой жетон.",
    ["奇怪，没人回应。"] = "Странно, никто не отвечает.",
    ["女神啊，她千万别和我玩什么不辞而别的把戏。"] = "О Богиня, лишь бы она не исчезла, не попрощавшись.",
    ["她……真的甘于平凡吗？"] = "Неужели она... правда довольна обычной жизнью?",
    ["她是我的好朋友，也是舞剧演员，平时喜欢研究些神秘学知识。"] = "Она моя хорошая подруга и танцовщица, в свободное время любит изучать мистические знания.",
    ["她渴望遗忘非凡，回归平凡生活，却没想过自己成为普通人时，也会渴望不平凡。"] = "Она жаждет забыть о необыкновенном и вернуться к обычной жизни, но не думала, что, став обычным человеком, будет тосковать по необыкновенному.",
    ["她的代价已经付过了……表演是我阻止的，那一幕让我想起了一些糟糕的记忆，下意识地动用了非凡能力。"] = "Её цена уже уплачена... Это я остановил представление. Та сцена напомнила мне о тяжёлых воспоминаниях, и я невольно применил необыкновенную способность.",
    ["好像很少在贝克兰德见到这些菜。"] = "Кажется, такие блюда редко встретишь в Бэкланде.",
    ["好厉害……您是怎么做到的？"] = "Потрясающе... Как вам это удалось?",
    ["好啊！心理医生……虽然我没看过心理医生，但名人身边需要专业的医生！"] = "Отлично! Психотерапевт... Хотя я никогда не ходил к психотерапевту, рядом со знаменитостью должен быть профессиональный врач!",
    ["好啊，我现在可不缺时间，没有客人需要我。你闻闻，这里比码头区最脏的下水道还臭。"] = "Пожалуйста, времени у меня сейчас хватает, гостям я не нужен. Понюхайте, здесь воняет хуже, чем в самой грязной канаве в районе порта.",
    ["好好，带你去。"] = "Хорошо, хорошо, отведу тебя.",
    ["好的！非常感谢。"] = "Хорошо! Огромное спасибо.",
    ["好香啊……但是尸体上长的菜……"] = "Как пахнет... но овощи, растущие на трупе...",
    ["好，我会的。"] = "Хорошо, я так и сделаю.",
    ["如果少出一点场地费，节省下来的钱，就能实现她的心愿了。所以……真的不能再少一点吗？我们真的没有更多的了……"] = "Если бы плата за место проведения была немного ниже, сэкономленных денег хватило бы на исполнение ее желания. Так... неужели нельзя быть ниже? У нас действительно больше нет...",
    ["如果我是安东尼神父，一定会拿权杖狠狠地敲他，像驱赶一条咬人的疯狗那样把他赶走！"] = "Если бы я был отцом Антонием, я бы обязательно сильно ударил его скипетром и прогнал прочь, как гнался за кусачей бешеной собакой!",
    ["妈妈！我要看！"] = "Мама! Я хочу посмотреть!",
    ["妈妈，这个叔叔好厉害！"] = "Мама, этот дядя такой крутой!",
    ["姐、姐姐！"] = "С-сестра!",
    ["它甚至能利用“心理学隐身”，一直躲藏在我们眼前。"] = "Оно даже может использовать «психологическую невидимость» и всё время прятаться у нас на виду.",
    ["家乡食材难得，既然你们不吃，我能用那些菜练练厨艺吗？"] = "Продукты из родных мест — большая редкость. Раз вы их не едите, можно мне потренироваться в готовке на этих блюдах?",
    ["对。里面的内容全是胡编乱造。"] = "Да. Содержимое внутри выдумано.",
    ["对不起！我们半夜来施肥，让整个温室变臭了。"] = "Простите! Мы пришли удобрять посреди ночи, и во всей теплице теперь воняет.",
    ["对啊，有什么问题？ 我家兔子叫格尔曼，用自己宠物的名字卖点货，这不犯法吧？"] = "Да, в чем проблема? Моего кролика зовут Герман, продажа некоторых товаров под именем моего питомца не является незаконной, верно?",
    ["对！汤姆告诉我，他前天值夜班时看到几个黑影。他们发出一种从来没听过的奇怪声音，围着角落，不知道是什么仪式……"] = "Да! Том рассказал, что позавчера в ночную смену видел несколько тёмных силуэтов. Они издавали странные звуки, каких он никогда не слышал, и стояли кругом в углу — не знаю, что за обряд...",
    ["少废话，别浪费时间了，快跟我们走！"] = "Хватит болтать, не тратьте время, идёмте с нами!",
    ["就是我，眼熟吗？"] = "Это я. Узнаёшь?",
    ["就是说，作物要丰收，需要施肥嘛，比如有机肥什么的。"] = "То есть, чтобы собрать хороший урожай, нужны удобрения, например органические.",
    ["就算打不过……来都来了！"] = "Даже если я не смогу победить... Я уже здесь!",
    ["就算那些故事是假的……至少我为了解她，实实在在地试过了。"] = "Даже если эти истории лживы... по крайней мере, я действительно пытался понять ее.",
    ["已经谈好了吗？"] = "Вы уже договорились?",
    ["帕金娜的表演……出了点小意外。"] = "С выступлением Пакины... вышла небольшая неприятность.",
    ["帕金娜，你怎么在这里？我……刚刚和经理吵了一架，我把他炒了，哈哈。"] = "Пакина, что ты здесь делаешь? Я... только что поссорился с менеджером и уволил его, ха-ха.",
    ["帕金娜，你身上带着的那个东西……有些不对劲。"] = "Пакина, с тем, что ты носишь при себе... что-то не так.",
    ["帕金娜，刚刚听说你被停职了，对不起。"] = "Пакина, я только что узнал, что тебя отстранили. Прости.",
    ["帕金娜，对，对不起！"] = "Пакина, п-прости!",
    ["帕金娜，阿斯塔给你的信。"] = "Пакина, письмо тебе от Асты.",
    ["帮她"] = "Помочь ей",
    ["平凡的生活似乎也没那么糟糕了。"] = "Обычная жизнь, похоже, не так уж и плоха.",
    ["幸运的是菜长得还挺好，<P_Heart>（思索）</>好到有点离谱了。"] = "К счастью, овощи растут очень хорошо, <P_Heart>(задумчиво)</> настолько хорошо, что это уже за гранью разумного.",
    ["异教徒？"] = "Еретик?",
    ["异教徒？这里有异教徒？！"] = "Еретик? Здесь есть еретик?!",
    ["当然。"] = "Конечно.",
    ["当然。总比在这儿……挑战狼鱼罐头强。"] = "Конечно. Это лучше, чем пытаться съесть... консервы из зубатки.",
    ["当然不是，我早忍不了那老东西了。今天休息日，非要叫我来加班，还让我接你的班，说什么“你是下一个‘贝克兰德的明日之星’”，真是疯了……"] = "Конечно нет, я давно не выношу этого старика. Сегодня мой выходной, а он заставил меня выйти на сверхурочную и ещё подменить тебя, мол, «ты — следующая восходящая звезда Бэкланда». Он совсем спятил...",
    ["当然认识，你在这卖票一年了，你不在，售票亭都只能自助售票！"] = "Конечно знаю, вы продаёте здесь билеты уже год. Без вас в кассе можно было бы купить билет только самообслуживанием!",
    ["当然！我打开门窗，用排气扇猛吹，还在观赏区喷洒了香水。但那都只能管一小会，第二天还是那么臭！"] = "Конечно! Я открывал окна и двери, включал вытяжку на полную и даже опрыскал смотровую зону духами. Но хватало ненадолго, на следующий день снова та же вонь!",
    ["当然，我们可是冒着减产的风险答应过你的！"] = "Конечно, мы же согласились на ваши условия, рискуя снизить выпуск!",
    ["当然，我走之前一定给你做一个新的护身符，这次一定不会出意外，我已经精心挑选了适合的日期和时间……"] = "Конечно, перед отъездом я обязательно сделаю тебе новый амулет. В этот раз никаких неприятностей не будет, я тщательно выбрал подходящие дату и время...",
    ["很抱歉给人们带来困扰，我们会马上停止施用肥料。"] = "Мы очень сожалеем, что доставили людям неудобства, и немедленно прекратим использовать удобрение.",
    ["很高兴你做出了这个决定，也许这正是改变的契机。"] = "Я рад, что ты принял это решение, возможно, это и есть повод для перемен.",
    ["得了得了，小心吹牛吹太大，圆不回来了啊。"] = "Хорошо, хорошо, будьте осторожны, не хвастайтесь слишком сильно и не подкрепляйте это.",
    ["得尽快找到她。"] = "Нужно как можно скорее найти её.",
    ["心意有什么用？我连外面变成什么样了都不知道，还想学人家英雄救美……"] = "Какой смысл в намерениях? Я даже не знаю, во что превратился внешний мир, а мне хотелось сыграть героя, спасающего красоту...",
    ["怎么会呢，团长不是说，游客们都很需要你吗？"] = "Как же так? Разве глава труппы не говорил, что туристы очень в тебе нуждаются?",
    ["怎么办，阿斯塔到底在哪里……"] = "Что же делать, где же всё-таки Аста...",
    ["怎么样，花园的臭味已经消失了吧？"] = "Ну как, вонь в саду уже исчезла?",
    ["怎么样？"] = "Как это?",
    ["总之，是英雄救美的桥段。不过贝克兰德哪来的海盗？我也遇不上什么贵族小姐。就算遇上，凭我这身板……也打不过。"] = "Короче говоря, это герой, спасающий образ красоты. Но откуда в Баклунде могли взяться пираты? И я не могу встретить ни одной благородной дамы. Даже если бы я это сделал, с моим телосложением... я бы не смог победить.",
    ["总算能歇一歇了。让我看看……书中还写了什么……"] = "Наконец-то я могу сделать перерыв. Дай-ка посмотреть... что еще написано в книге...",
    ["您也别太往心里去。至少……这份心意是好的。"] = "Не принимайте это близко к сердцу. По крайней мере... намерение было хорошим.",
    ["您好，这里是慈善医院，请问有什么可以帮您的？"] = "Здравствуйте, это Благотворительная больница, чем я могу вам помочь?",
    ["您接下来……？"] = "А дальше вы...?",
    ["您是好心，我们心里都明白，多谢。"] = "У вас хорошие намерения, мы понимаем, спасибо.",
    ["情、情趣？"] = "Р-романтическое развлечение?",
    ["想学吗？"] = "Хочешь научиться?",
    ["我……"] = "Я...",
    ["我……我是……"] = "Я... я...",
    ["我、我吗？那我也买一张票！"] = "Я, я? Тогда я тоже куплю билет!",
    ["我、我听见有人喊救命……"] = "Я, я услышал, как кто-то звал на помощь...",
    ["我、我就是想尝尝……书上说格尔曼最怕这个，我想要赢……"] = "Я, я просто хотел попробовать... в книге сказано, что Герман боится этого больше всего, я хотел победить...",
    ["我了解你们的难处，只是……"] = "Я понимаю твои трудности, просто...",
    ["我们不会用太多地方的。届时只会有几位至亲，还有几个最要好的朋友到场。"] = "Мы не займем много места. Присутствуют лишь несколько близких родственников и несколько лучших друзей.",
    ["我们不如去问团长，他总该认识自己团里的明星人物！"] = "Давайте лучше спросим у главы труппы, он-то наверняка знает звезду своей же труппы!",
    ["我们晚上来浇水施肥，被误认成坏人了啊，哈哈哈。"] = "Мы пришли ночью поливать и удобрять растения, а нас приняли за злодеев, ха-ха-ха.",
    ["我们的计划被发现了！"] = "Наш план раскрыт!",
    ["我会的，很抱歉今天让你错过了演出，下次来马戏团，我请你看演出！"] = "Обязательно. Простите, что сегодня вы пропустили представление. В следующий раз приходите в цирк, я приглашаю вас на выступление!",
    ["我会的，非常期待。"] = "Обязательно, я очень жду этого.",
    ["我叫{{PlayerName}}，你刚才说，我们是老乡？"] = "Меня зовут {{PlayerName}}. Вы только что сказали, что мы земляки?",
    ["我听说埋在地下的，是很多被诅咒的法宝。它们的力量要是释放出来，足以摧毁整个贝克兰德！"] = "Я слышал, что под землей похоронено множество проклятых магических артефактов. Если бы их сила была высвобождена, этого было бы достаточно, чтобы уничтожить весь Баклунд!",
    ["我听说的好像也是这个版本……"] = "Кажется, я тоже слышал такую ​​версию...",
    ["我听说的版本怎么跟你的不一样啊？"] = "Почему версия, которую я слышал, отличается от твоей?",
    ["我女儿她……该不会也……"] = "Моя дочь... могла бы она тоже быть...",
    ["我女儿整天格尔曼长格尔曼短的，我就想做点他做过的事，跟她搭上话。"] = "Моя дочь весь день говорит о Германе, я просто хотел сделать кое-что из того, что он делал, чтобы завязать с ней разговор.",
    ["我女儿，十四了。以前什么都跟我说，现在我说什么她都嫌烦。"] = "Моя дочь, ей четырнадцать. Раньше она мне все рассказывала, но теперь ее раздражает все, что я говорю.",
    ["我想做义工。听说格尔曼·斯帕罗曾在这里做过义工。"] = "Я хочу стать волонтером. Я слышал, Герман Воробей однажды работал здесь добровольцем.",
    ["我想帮她解除暗示。经历了一年的售票生活，她或许会有新的感悟。"] = "Я хочу помочь ей снять внушение. После года жизни продавщицей билетов она, возможно, поймёт что-то новое.",
    ["我想要……向格尔曼致敬！"] = "Я хотел... отдать должное Герману!",
    ["我想，女神不会让一对虔诚的爱侣失望的。"] = "Думаю, Богиня не подведет пару преданных влюбленных.",
    ["我愿为你供奉世界上最贵重的珍宝，为你一字一句抄写最冗长的经书！"] = "Я готов предложить вам самые драгоценные сокровища в мире и переписать для вас самые длинные отрывки из Священных Писаний слово за словом!",
    ["我懂了，完全说得通。"] = "Я понял, всё сходится.",
    ["我收回之前的话，帕金娜，你是剧场不可分割的一员……"] = "Я беру свои слова назад, Пакина. Ты неотъемлемая часть театра...",
    ["我是平凡的马戏团售票员……"] = "Я обычная кассирша цирка...",
    ["我是非凡者……我治愈过几百个病人……"] = "Я Потусторонний... Я исцелил сотни больных...",
    ["我来介绍一下，这位是{{PlayerName}}警官，之前我听你念叨，什么污染，脑子被吃掉……这很危险的！"] = "Позвольте представить: это офицер {{PlayerName}}. Раньше я слышал, как ты бормотал что-то про заражение, про то, что мозг съедают... Это очень опасно!",
    ["我每天八点起床，骑二十分钟脚踏车来这里，站八个小时，卖两百多张票。吃饭要快，因为孩子们等着我。"] = "Каждый день я встаю в восемь, двадцать минут еду сюда на велосипеде, стою восемь часов и продаю больше двухсот билетов. Ем я быстро, ведь дети ждут меня.",
    ["我看看……“格尔曼唯一惧怕之物——码头摊贩的狼鱼罐头…… ”"] = "Дай взглянуть... «Единственное, чего боится Герман, — консервированная зубатка у портовых торговцев...»",
    ["我看还差得远呢，还不如直接送去春……呃……"] = "По-моему, этого мало, лучше сразу отправить их на вес... э-э...",
    ["我竟然会相信你这个吹牛的骗子。现在好了，生意越来越差，政府要问责，别墅要关门，我也要失业……"] = "Как я мог поверить такому хвастуну и обманщику! Теперь дела всё хуже, правительство требует ответа, особняк закроют, а я останусь без работы...",
    ["我认为应该尊重她之前的选择。"] = "Я считаю, что нужно уважать её прежний выбор.",
    ["我讨厌你们！我不要跟你们一起玩了！"] = "Я ненавижу вас всех! Я больше не хочу с тобой играть!",
    ["我记得自己叫艾玛，是位马戏团知名人士……其他都想不起来了。"] = "Я помню, что меня зовут Эмма и я известная личность в цирке... остального не помню.",
    ["我试试看，能不能根据信上残留的气息找到她。"] = "Попробую найти её по остаточному запаху на письме.",
    ["我该去治疗了。"] = "Мне пора на лечение.",
    ["我还有事"] = "у меня есть другие дела",
    ["我逃走了，想重新找到生活的意义…"] = "Я сбежал, чтобы заново найти смысл жизни…",
    ["或许找她问问能获得更多线索。"] = "Возможно, расспросив её, удастся узнать больше.",
    ["或许还坐不满两排长椅呢，宾客稀少，收拾起来也没那么麻烦。"] = "Возможно, оно не смогло бы заполнить даже два ряда скамеек; при небольшом количестве гостей уборка не представляет особых хлопот.",
    ["房间门是开着的。"] = "Дверь в комнату открыта.",
    ["所有人脸上都挂着笑容，一切都充满希望。"] = "На лицах у всех были улыбки, и всё было полно надежды.",
    ["打扰了。我刚刚在教堂后面的花圃里采了些花，想着或许有人用得上。"] = "Прошу прощения. Я только что нарвал цветов в саду за церковью, подумал, вдруг кому-нибудь пригодятся.",
    ["抱歉，无意间听到了你们的谈话，我是{{PlayerName}}，一名警察。"] = "Простите, я невольно услышал ваш разговор. Я {{PlayerName}}, полицейский.",
    ["抱歉，没想到惊扰了您。"] = "Прошу прощения, не думал, что побеспокою вас.",
    ["拒绝"] = "Мусор",
    ["拿走拿走，都归你了。"] = "Берите, берите, всё ваше.",
    ["挺眼熟……好像在哪见过……"] = "Очень знакомо… Кажется, я где-то это видел…",
    ["接受"] = "Принимать",
    ["放心吧，就算你什么也不知道，我们也不会孤立你的，哈哈哈！"] = "Не волнуйтесь, даже если вы ничего не знаете, мы не будем вас изолировать, ха-ха-ха!",
    ["放心，我会的。"] = "Не волнуйся, я это сделаю.",
    ["救命！"] = "Помощь!",
    ["无穷的信息流穿梭而出，像无穷的呓语。它们化成陆地，它们化成大海，大海变成陆地，陆地又变成大海，人诞生又消失，时间前进又倒转。"] = "Бесконечные потоки информации хлынули вперед, словно непрерывный шепот. Они стали сушей, затем морем; море превратилось в сушу, а земля снова в море. Люди рождались и исчезали с течением времени вперед и назад.",
    ["既可以消化魔药，又可以种出家乡的味道，我最喜欢种菜了！"] = "И зелье переварить, и вкус родного дома вырастить — больше всего я люблю возиться с грядками!",
    ["既然你是名人，我们从你熟悉的地方开始调查？"] = "Раз вы знаменитость, начнём расследование с места, которое вам знакомо?",
    ["明星有什么用！没你卖票，我们表演给谁看？"] = "Какой толк от звезды! Без тебя, продающего билеты, для кого нам выступать?",
    ["明白了。米勒先生，表格填好后，请随格莱特先生过去，他会安排您的工作。"] = "Понял. Господин Миллер, после заполнения формы, пройдите, пожалуйста, к господину Глету, он организует вашу работу.",
    ["是一扇大铁门…….非常巨大，有整个教堂那么大，里面黑洞洞、阴森森的，风一吹就吱嘎吱嘎响。我当时吓呆了，事后甚至怀疑那是幻觉！"] = "Это были огромные железные ворота... Невероятно огромные, размером с целую церковь! Внутри зияла тьма, веяло жутью, а от ветра они скрипели. Я тогда застыл от ужаса, а потом даже подумал, что это была галлюцинация!",
    ["是啊！我想起我卖票的日子了！"] = "Да! Я вспомнил, как продавал билеты!",
    ["是啊！这味道不知道什么时候有的，一天比一天臭，熏得客人们都不来了！"] = "Да! Неизвестно, когда появился этот запах, но с каждым днём он всё хуже, и от вони посетители перестали приходить!",
    ["是啊，我的亲亲狒狒不吃东西，可演出就快开始了！"] = "Да, мой милый бабуин не ест, а представление вот-вот начнётся!",
    ["是的！昨天的表演中，有一股无形的力量拉扯着我，阻碍了我的行动。"] = "Да! На вчерашнем представлении невидимая сила тянула меня и мешала двигаться.",
    ["是的，原来我是因为摔到了脑袋，才会失忆。"] = "Да, оказывается, я потерял память, потому что ударился головой.",
    ["是的，女士，我保证，这会很快、很平静。"] = "Да, госпожа, обещаю, всё будет быстро и спокойно.",
    ["是真的是真的！我悄悄告诉你们，之前有一次月圆夜，我偷溜进教堂，看到了很不寻常的东西！"] = "Это правда, это правда! Ребята, я вам тихо скажу: накануне была ночь полнолуния, когда я пробрался в церковь и увидел нечто очень необычное!",
    ["最近她整天念叨一个叫“格尔曼”的人，特别崇拜他。我想，不如从她的偶像入手，多了解她一些——所以买了这个。"] = "Недавно она целый день говорила о ком-то по имени «Герман», она действительно восхищается им. Я подумал, почему бы не начать с ее кумира, чтобы лучше ее понять — и купил это.",
    ["有时候天气很好，有时候天气不好，不管怎样，路上的风景总是看不腻。"] = "Иногда погода хорошая, иногда плохая, но в любом случае видами по дороге невозможно насытиться.",
    ["有机肥，比如发酵腐烂的秸秆、动物残体和排泄物？你们该不会是说……"] = "Органические удобрения — вроде перебродившей гнилой соломы, останков животных и экскрементов? Вы же не хотите сказать...",
    ["有道理，走。"] = "Резонно, идём.",
    ["有道理，这样她了解真相后，还有重新选择的机会。"] = "Резонно, так, узнав правду, она ещё сможет сделать новый выбор.",
    ["本以为自己是大明星，结果就是个谁也不认识的售票员。"] = "Думал, что я большая звезда, а оказался никому не известным кассиром.",
    ["本森，收收你那粉丝心态，宣传的时候说得那么夸张，现场她就平平无奇地走下了台阶！"] = "Бенсон, умерь свой фанатизм! В рекламе ты так всё преувеличивал, а вживую она просто обыденно спустилась по ступеням!",
    ["来人啊！警卫！"] = "Эй, сюда! Стража!",
    ["来都来了。朋友，劳烦帮我拍一张。拿给我女儿瞧瞧——让她知道，她爸为了她，连这种东西都敢碰。"] = "Раз уж мы здесь. Друг, можешь помочь мне сфотографироваться? Я покажу это своей дочери — пусть она знает, что ее отец осмелился прикоснуться к этой штуке ради нее.",
    ["格尔曼最怕狼鱼罐头？谁跟您说的？"] = "Герман больше всего боится консервов из рыбы-волка? Кто тебе это сказал?",
    ["格尔曼？那位疯狂的冒险家……来医院做义工？好吧……我先帮您登记。姓名？"] = "Герман? Этот сумасшедший авантюрист... пришел в больницу добровольцем? Хорошо... Сначала я тебя зарегистрирую. Имя?",
    ["检修的工人排查过了，警察也来过了，什么都没有！现在告示已经发了，帕金娜，我不可能为你胡乱的猜测再多花一苏勒！"] = "Рабочие по ремонту всё проверили, полиция тоже приходила — ничего нет! Объявление уже вывешено, Пакина, и я не потрачу ни одного лишнего сулера на твои пустые догадки!",
    ["每天清晨，骑着脚踏车上班，经过不同的街道。"] = "Каждое утро еду на работу на велосипеде, проезжая по разным улицам.",
    ["气氛都烘托到位了，就算是摔死，也要把表演完成啊。"] = "Атмосфера создана как надо — даже если разобьюсь насмерть, представление нужно довести до конца.",
    ["没关系的，阁下。冒昧问一句，您并非帕金娜的粉丝吧？我看您对她，似乎没有那种见到偶像时该有的热切。 "] = "Ничего страшного, ваше превосходительство. Позвольте спросить: вы ведь не поклонник Пакины? Мне кажется, в вас нет того пыла, какой бывает при встрече с кумиром.",
    ["没想到在这个世界上，种个菜都能遇到危险，<P_Heart>（苦笑）</>还是没法习惯啊。"] = "Не думал, что в этом мире даже выращивание овощей может быть опасным. <P_Heart>(Горькая улыбка)</> Всё никак не привыкну.",
    ["没想起来，可我如果不是名人，不被人需要，生活还有什么意义？"] = "Не вспомнил. Но если я не знаменитость и никому не нужен, какой смысл в жизни?",
    ["没有人记得我……没有人依赖我……"] = "Никто не помнит меня... Никто на меня не полагается...",
    ["没有啊，你是……"] = "Нет, а ты кто?..",
    ["没钱？我看不如送你去春夜沙龙，凭你的模样，不出三天什么钱都能凑齐了。"] = "Нет денег? По-моему, тебя лучше отправить в Салон Весенней ночи. С такой внешностью ты соберёшь любые деньги меньше чем за три дня.",
    ["海盗女王……把贵族小姐按在墙上？怎么听着有点奇怪……"] = "Королева пиратов... прижала благородную даму к стене? Почему это звучит немного странно...",
    ["混沌中，你的意识仿佛落入一个奇妙的地方。"] = "Кажется, что в этом хаосе ваше сознание попадает в чудесное место.",
    ["演出！演出！"] = "Представление! Представление!",
    ["然后……买本正版的《大冒险家》重新看看。总不能一直拿着盗版书误导自己。"] = "Тогда... купите подлинный экземпляр «Великого искателя приключений» и прочитайте его еще раз. Я не могу продолжать вводить себя в заблуждение пиратской книгой.",
    ["爱德华先生，我知道……教堂的场地费是有定例的。只是……您看能不能再商量一下？哪怕减免一点点也好。"] = "Мистер Эдвард, я понимаю... арендная плата за помещение церкви строго установлена. Но... быть может, мы могли бы договориться? Хоть о крошечной скидке.",
    ["爱德华先生，诺拉她……想在婚礼上多摆些铃兰花。就是那种——白色的，一簇一簇的，闻起来很清香的那种。"] = "Мистер Эдвард, Нора... она хочет, чтобы на свадьбе было больше ландышей. Знаете, белые, собранные в гроздья, пахнут так свежо.",
    ["玛蒂尔达！求你出来见我一面吧！"] = "Матильда! Пожалуйста, выйдите и посмотрите на меня!",
    ["现在还是不清楚艾玛失忆的原因……"] = "До сих пор неясна причина потери памяти Эммы...",
    ["理论上，尸体上长的菜和有机肥浇灌的菜没有成分区别，食用安全是可以保障的。"] = "Теоретически, овощи, выросшие на трупах, и овощи, политые органическим удобрением, не отличаются по составу, так что безопасность употребления в пищу гарантирована.",
    ["盗……盗版？"] = "Пи... пиратский?",
    ["看我露一手！"] = "Смотрите, как это делается!",
    ["看来异教徒之说是个误会，那味道应该和前辈们没有关系。"] = "Похоже, разговоры о еретиках были недоразумением, этот запах не должен быть связан с предшественниками.",
    ["看来必须找到臭味的源头，才能彻底治理这个问题。"] = "Похоже, нужно найти источник зловония, чтобы полностью решить эту проблему.",
    ["看着他们饱餐了一顿后……"] = "Глядя, как они сытно поели...",
    ["看见刚刚离开剧场的那位绅士了吗？他有意为剧场出资，你之前想要的那些舞台道具都能换新的了……"] = "Видишь того джентльмена, что только что вышел из театра? Он намерен вложиться в театр, и весь тот реквизит, что ты хотел, можно будет заменить новым...",
    ["看！在那里！"] = "Смотреть! Вон там!",
    ["真可惜，我平时工作忙得很，到时候恐怕抽不出身来为你们作见证。"] = "Как жаль, я обычно очень занят на работе, боюсь, тогда у меня не будет времени, чтобы свидетельствовать за вас.",
    ["真好吃，外脆里嫩，<P_Heart>（嚼嚼）</>麻辣鲜香，太香了。"] = "Как вкусно, снаружи хрустит, внутри нежное, <P_Heart>(жуёт)</> остро, остро и ароматно, просто восхитительно.",
    ["真是位细心的{{先生|女士}}。你在疑惑，脱离了粉丝的身份，我为什么要帮助一位陌生人？"] = "Какой внимательный {{господин|госпожа}}. Вы удивляетесь: перестав быть поклонником, зачем я помогаю незнакомцу?",
    ["真是烦人啊！吵得我耳朵都要起茧子了。"] = "Как это раздражает! Здесь так шумно, что у меня в ушах появятся мозоли.",
    ["真的假的"] = "Серьезно?",
    ["真的好香啊……"] = "Как же вкусно пахнет...",
    ["真的？"] = "Действительно?",
    ["真稀奇，它这么喜欢你……对了，你们找我有事吗？"] = "Как странно, вы ему так нравитесь... Кстати, у вас ко мне какое-то дело?",
    ["祝你度过非凡的一天！买票这边走！"] = "Желаю вам необыкновенного дня! За билетами сюда!",
    ["竟然有这么可怕的事？"] = "Есть на самом деле такая ужасающая вещь?",
    ["笨蛋！笨蛋！"] = "Дурак! Дурак!",
    ["等你！笨蛋！"] = "Жду тебя! Болван!",
    ["等等！别在这里……"] = "Ждать! Не делайте этого здесь...",
    ["等等！我的票！"] = "Подождите! Мой билет!",
    ["等等，一句话还不能说明他的来历。"] = "Погоди, одной фразой его происхождение не объяснить.",
    ["等等，你不会是那些异教徒的同伙吧？"] = "Погоди, ты ведь не сообщник этих еретиков?",
    ["算了吧"] = "Забудь это",
    ["算了，先解决眼前的事情，请问，几位深夜在这做什么？"] = "Ладно, сначала разберёмся с делом. Позвольте спросить, что вы все делаете здесь посреди ночи?",
    ["管他呢，我要开动了！    "] = "Да ну всё! Я приступаю!",
    ["米莉小姐，你们已经停止施肥了吗？"] = "Госпожа Милли, вы уже прекратили вносить удобрения?",
    ["糟了……阿斯塔说她要离开，信上还写了“我再也忍受不了了！我要疯了！”"] = "Беда... Аста сказала, что уходит, а в письме было написано: «Я больше не могу терпеть! Я схожу с ума!»",
    ["约定"] = "Уговор",
    ["经过一段时间的努力，莱昂终于完成了今日的义工工作。"] = "После некоторых усилий Леон наконец завершил сегодняшнюю волонтерскую работу.",
    ["结合已经知道的信息……"] = "Сопоставив уже известную информацию...",
    ["罗塞尔……呃！头好痛！"] = "Россель... Ох! Как голова болит!",
    ["老乡？"] = "Земляк?",
    ["老板，你这上面写着“格尔曼同款”，下面又写“与《大冒险家》无关”？"] = "Босс, здесь написано «Любимец Германа», а внизу написано «Не имеет отношения к «Великому искателю приключений»»?",
    ["老詹说得对，{{兄弟|姐妹}}，你可以告诉游客和这儿的打工人，过几天臭味就会完全消失啦！"] = "Старина Джеймс прав, {{брат|сестра}}, можешь сказать туристам и местным работникам, что через пару дней запах полностью исчезнет!",
    ["能让我来试试吗？"] = "Позвольте мне попробовать?",
    ["臭味到底是哪来的？这该死的花园一定是被诅咒了！"] = "Откуда вообще эта вонь? Этот проклятый сад наверняка проклят!",
    ["臭味肯定是那群异教徒搞出来的！"] = "Эту вонь наверняка устроили те еретики!",
    ["至于明天……啊，快看，我们种下的娃娃菜终于发芽了！"] = "А что до завтра... ах, смотрите, посаженная нами пекинская капуста наконец проросла!",
    ["艾玛小姐，能让我尝试帮你找回记忆吗？如果失败，我还认识一位专业的心理医生。"] = "Госпожа Эмма, позволите мне попробовать помочь вам вернуть память? Если не получится, я знаю одного опытного Психотерапевта.",
    ["艾玛是观众途径非凡者，她对自己使用心理暗示，忘记了过去的身份，却不小心忘得太多……"] = "Эмма — Потусторонний Пути Зрителя. Она применила к себе психологическое внушение, чтобы забыть прежнюю личность, но случайно забыла слишком много...",
    ["艾玛！你总算回来了！"] = "Эмма! Ты наконец вернулась!",
    ["艾玛，你想起一切了？"] = "Эмма, ты всё вспомнила?",
    ["艾玛，我觉得作为售票员的你，好像也挺非凡的。"] = "Эмма, мне кажется, ты как кондуктор тоже довольно необычная.",
    ["艾玛，还记得你是谁吗？"] = "Эмма, ты помнишь, кто ты?",
    ["英雄救美我学不来，他怕的东西，总有我不怕的吧？ 走！"] = "Я не могу научиться сохранять красоту, но, должно быть, он чего-то боится, чего не боюсь я! Пойдем!",
    ["荖詹 ，你是甜豆花哌還湜咸豆花派？"] = "Лао Чжань, ты за сладкий доуха или за солёный?",
    ["莪恏想念甜豆花。"] = "Я так скучаю по сладкому доуха.",
    ["莱昂·米勒。"] = "Леон Миллер.",
    ["菜心朂菦洧點蔫，嘚想想刅琺。"] = "Капуста в последнее время что-то вянет, надо придумать, как её спасти.",
    ["葛朗经理，舞台一定有问题。"] = "Управляющий Герань, с этой сценой точно что-то не так.",
    ["虽然我今天才认识你，但……也祝你度过“非凡”一天。"] = "Хоть мы познакомились только сегодня, но... желаю вам «необыкновенного» дня.",
    ["表演事故？周围的人也许了解更多，去问问他们吧。"] = "Несчастный случай на представлении? Люди вокруг могут знать больше, спроси их.",
    ["表演开始！"] = "Представление начинается!",
    ["见鬼的，你难道闻不到？"] = "Чёрт побери, неужели ты не чувствуешь запах?",
    ["观众朋友们，我的表演只是前菜！马戏团内还有狒狒跳舞等更精彩的演出！小朋友可享半价优惠！"] = "Дорогие зрители, моё выступление — лишь закуска! В цирке вас ждут ещё более яркие номера, например танцы павианов! Детям скидка 50%!",
    ["解释"] = "Объяснять",
    ["警官……今早有意识的时候，我就坐在长椅上。"] = "Офицер... Когда я утром пришёл в сознание, я сидел на скамейке.",
    ["警官……我只能待在帐篷里，不能见心理医生吗？"] = "Офицер... Мне можно сидеть только в палатке? Нельзя увидеться с Психотерапевтом?",
    ["警官，他连我这个大明星都不认识，就让他和亲亲狒狒待在一起吧！"] = "Офицер, он даже не узнал такую звезду, как я! Пусть остаётся с милыми бабуинами!",
    ["警官，现在，我最想知道自己为什么会突然失忆！"] = "Офицер, сейчас я больше всего хочу узнать, почему я вдруг потерял память!",
    ["警察？警察来过了，什么都没发现。"] = "Полиция? Полиция уже приезжала, ничего не обнаружила.",
    ["让我再看一眼你斗篷下碧绿如翡翠的瞳孔，听一听你低声念诵时温柔悦耳的嗓音！"] = "Позвольте мне еще раз взглянуть на ваши изумрудные зрачки под плащом и послушать ваш нежный и приятный голос, когда вы шепчете!",
    ["误会了。我们不过是找了个僻静地方，闹着玩罢了。"] = "Это недоразумение. Мы только что нашли тихое место, чтобы поиграть.",
    ["请问你认识一位叫艾玛的名人吗？"] = "Скажите, вы знаете известную личность по имени Эмма?",
    ["谁还想吃啊！"] = "Да кто это теперь захочет есть!",
    ["谁？！"] = "Кто?!",
    ["谢谢你和苏茜女士帮我恢复记忆！"] = "Спасибо вам и госпоже Сьюзи, что помогли мне вернуть память!",
    ["谢谢你和苏茜女士帮我恢复记忆！我现在可是干劲满满！"] = "Спасибо вам и госпоже Сьюзи, что помогли мне вернуть память! Теперь я полон сил!",
    ["谢谢，我想一个人静静。"] = "Спасибо, я хочу побыть один.",
    ["豆花当然要吃辣的。"] = "Доухуа, конечно, нужно есть острым.",
    ["走近看看"] = "Подойдите ближе, чтобы посмотреть",
    ["跟我们来就知道了。"] = "Пойдёмте с нами, и всё узнаете.",
    ["身上带着的东西……你是说这个护身符吗？这是阿斯塔送给我的，她不可能害我。"] = "То, что при мне... вы про этот амулет? Его подарила мне Аста, она не могла желать мне зла.",
    ["还是算了"] = "Неважно",
    ["还是算了，我的份也给你们吧。"] = "Ладно, пусть и моя доля достанется вам.",
    ["还有下下个月、下下下个月！"] = "И ещё через месяц, и ещё через один!",
    ["还有这儿，什么海盗女王救贵族小姐？根本没这回事！格尔曼救下的是一位被绑架的议员之子，哪来的什么小姐！"] = "А здесь какая Королева Пиратов спасает благородную даму? Этого никогда не было! Герман спас сына похищенного сенатора, откуда взялась дама!",
    ["还记得我认识的心理医生吗？她或许能给你答案。"] = "Помнишь психотерапевта, которого я знаю? Возможно, она даст тебе ответ.",
    ["这个很简单，首先你要……"] = "Это очень просто. Сначала тебе нужно...",
    ["这些钱肯定够了，不信你们数数。"] = "Этих денег точно хватит, не верите — пересчитайте.",
    ["这位{{先生|女士}}，你也是来做义工的吗？"] = "Этот {{Mr.|Ms.}}, ты тоже здесь, чтобы стать волонтером?",
    ["这位{{先生|女士}}，您如此体贴又温柔，来自您的祝福一定会灵验的！"] = "{{Сударь|Сударыня}}, вы так внимательны и нежны, ваше благословение непременно сбудется!",
